            GeostationarySatellite(name = "JAM-E JAM 1", longitudeDegrees = 33.9),
            GeostationarySatellite(name = "ECHOSTAR 25", longitudeDegrees = -109.9),
            GeostationarySatellite(name = "TJS-24", longitudeDegrees = 98.1),
        )

    /**
     * Longitudes are quoted to a tenth of a degree, so the index is keyed in tenths:
     * exact integer keys, and co-located satellites share one entry.
     */
    private val bySlot: Map<Int, List<GeostationarySatellite>> = all.groupBy { slotOf(it.longitudeDegrees) }

    private val byName: Map<String, GeostationarySatellite> = all.associateBy { it.name }

    /** Satellites at [longitudeDegrees], in catalogue order. Empty if none sits there. */
    fun at(longitudeDegrees: Double): List<GeostationarySatellite> = bySlot[slotOf(longitudeDegrees)].orEmpty()

    /** The satellite with that exact name, or null if the catalogue has no such entry. */
    fun named(name: String): GeostationarySatellite? = byName[name]

    private fun slotOf(longitudeDegrees: Double): Int = Math.round(longitudeDegrees * 10.0).toInt()
}
